head.script:
// [FAIL] gridView 의 oneditkeydown 이벤트에서 Body Cell 이
//        inputType="textImage" + embeddedInput="true" 인 경우
//        info.colIndex 가 undefined, info.colID 가 null 로 전달된다.
//        동일 조건의 inputType="text" / inputType="secret" Cell 에서는 정상 전달된다.
//        oneditkeyup 이벤트도 함께 출력하며 동일하게 undefined / null 로 전달된다.
//
//        Body Column 인덱스 0 = text     + embeddedInput (정상)
//        Body Column 인덱스 1 = secret   + embeddedInput (정상)
//        Body Column 인덱스 2 = textImage + embeddedInput (결함)

scwin.onpageload = function () {
};



// 이벤트 파라미터 출력 공통 함수
//  - 판정에 필요한 colIndex / colID 만 출력한다.
//  - 어떤 Cell 에서 입력했는지는 해당 Cell 의 값(oldValue)으로 구분한다.
scwin.printInfo = function (eventName, info) {
    scwin.setReturnValue(eventName + " : colIndex = " + info.colIndex + " / colID = " + info.colID + "  (입력 Cell : " + info.oldValue + ")");
};



// oneditkeydown : Body Cell 의 편집 영역에서 키를 누를때 발생
scwin.target1_oneditkeydown = function (info) {
    scwin.printInfo("oneditkeydown", info);
};



// oneditkeyup : Body Cell 의 편집 영역에서 키를 뗄때 발생 (동일 증상 여부 확인용)
scwin.target1_oneditkeyup = function (info) {
    scwin.printInfo("oneditkeyup  ", info);
};



// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
